    out.push("【" + kindLabel(kindId) + "】")
    out.push("")
    group.forEach((n) => {
      out.push("File: " + pathLabel)
      out.push("Source: markdown")
      out.push("")
      const linesLabel = typeof n.start === "number" && typeof n.end === "number" && n.end > n.start
