      out.push("Excerpt:")
      excerptOf(n).forEach((l) => out.push("> " + l))
      out.push('User comment: "' + n.note + '"')
      if (isStale(n)) out.push("(注：该处内容可能已变化，请按原文定位)")
      out.push("")
    })
    firstGroup = false
  })
  while (out.length > 0 && out[out.length - 1] === "") out.pop()
  return out.join("\n")
}
